import type { PromptLanguage } from './types';

/** The complete, locale-specific instructions for the genealogy Deep Research
 * stages. Machine-facing JSON keys, citation syntax and source ids intentionally
 * remain unchanged in every locale. */
export interface GenealogyDeepResearchPromptPack {
  planner(sectionTarget: number, focusPersonName?: string): string;
  writer(focusPersonName?: string, narrativeRules?: readonly string[]): string;
  editor: string;
  finalizer: string;
  auditor: string;
}

/** Deterministic copy emitted when the genealogy workflow cannot rely on model
 * output. These strings are user-visible, while JSON keys and source ids remain
 * language-neutral protocol fields. */
export interface GenealogyDeepResearchRuntimeCopy {
  document: string;
  work: string;
  author: string;
  snapshotFocus(name: string): string;
  snapshotFamily: string;
  planning(count: number): string;
  maxSections(count: number): string;
  drafting(title: string): string;
  degraded: string;
  assembling: string;
  verificationNextStep: string;
  doneSingle(pages: number): string;
  doneSections(sections: number, pages: number): string;
  section(index: number): string;
  firstSection: string;
  mentions(names: string): string;
  archiveOrLibrary: string;
  primarySource: string;
  secondarySource: string;
  focusOrigins(name: string): string;
  focusOriginsPurpose: string;
  focusLife(name: string): string;
  focusLifePurpose: string;
  synthesis: string;
  synthesisPurpose: string;
  familyOverview: string;
  familyOverviewPurpose: string;
  documentedLives: string;
  documentedLivesPurpose: string;
  focusReport(name: string, objective: string): string;
  familyReport(objective: string): string;
  degradedNoSources: string;
}

