export function genealogyDeepResearchPromptPack(language: unknown): GenealogyDeepResearchPromptPack {
  const value = typeof language === 'string' && (LANGUAGES as readonly string[]).includes(language)
    ? language as PromptLanguage
    : 'en';
  return PACKS[value];
}

export function genealogyDeepResearchRuntimeCopy(language: unknown): GenealogyDeepResearchRuntimeCopy {
  const value = typeof language === 'string' && (LANGUAGES as readonly string[]).includes(language)
    ? language as PromptLanguage
    : 'en';
  return RUNTIME_COPY[value];
}
